const SANS = "Unbounded, system-ui, -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif";
const MONO = "Geist Mono, ui-monospace, SFMono-Regular, Menlo, Consolas, monospace";

/**
 * Shared theme configuration for consistent branding across canvas renders.
 */
function themeColors() {
  const isDark = document.documentElement.classList.contains("dark");
  return {
    isDark,
    bg: isDark ? "#09090b" : "#efe7d9",
    surface: isDark ? "#18181b" : "#e1d5c2",
    text: isDark ? "#fafafa" : "#1b1814",
    muted: isDark ? "#a1a1aa" : "#5f574f",
    subtle: isDark ? "#52525b" : "#6b6259",
    accent: isDark ? "#fbbf24" : "#d97706", // Amber for Sellers
    accentSoft: isDark ? "#451a03" : "#fef3c7",
    emerald: isDark ? "#10b981" : "#059669",
    red: isDark ? "#ef4444" : "#dc2626",
    sky: isDark ? "#38bdf8" : "#0284c7",
    border: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.12)",
    grid: isDark ? "rgba(255,255,255,0.03)" : "rgba(0,0,0,0.04)",
    glowPrimary: isDark ? "rgba(251,191,36,0.12)" : "rgba(251,191,36,0.1)",
  };
}

/**
 * Helper to draw rounded rectangles on the canvas.
 */
function fillRoundRect(ctx, x, y, w, h, r, fill, stroke = null) {
  const radius = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
  ctx.fillStyle = fill;
  ctx.fill();
  if (stroke) {
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}

/**
 * Renders a Twitter-style verified badge.
 */
function drawVerifiedBadge(ctx, x, y, size, t) {
  ctx.save();
  const color = t.accent;
  
  // Starburst shape for the badge background
  ctx.beginPath();
  const points = 8;
  const innerRadius = size * 0.4;
  const outerRadius = size * 0.5;
  const cx = x + size / 2;
  const cy = y + size / 2;
  
  for (let i = 0; i < points * 2; i++) {
    const r = i % 2 === 0 ? outerRadius : innerRadius;
    const angle = (Math.PI / points) * i;
    const px = cx + Math.cos(angle) * r;
    const py = cy + Math.sin(angle) * r;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();

  // Checkmark
  ctx.beginPath();
  ctx.strokeStyle = t.bg;
  ctx.lineWidth = size * 0.12;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.moveTo(cx - size * 0.18, cy);
  ctx.lineTo(cx - size * 0.04, cy + size * 0.14);
  ctx.lineTo(cx + size * 0.2, cy - size * 0.12);
  ctx.stroke();
  
  ctx.restore();
}

/**
 * Multi-line text renderer with automatic wrapping and overflow handling.
 */
function drawTextLines(ctx, text, x, y, maxWidth, lineHeight, maxLines) {
  const words = String(text || "").split(/\s+/).filter(Boolean);
  const lines = [];
  let line = "";
  
  for (const word of words) {
    const next = line ? `${line} ${word}` : word;
    if (ctx.measureText(next).width <= maxWidth || !line) {
      line = next;
    } else {
      lines.push(line);
      line = word;
    }
    if (lines.length >= maxLines) break;
  }
  
  if (line && lines.length < maxLines) lines.push(line);
  
  // Truncate last line if needed
  if (lines.length === maxLines) {
    let last = lines[lines.length - 1];
    if (ctx.measureText(`${last}...`).width > maxWidth) {
      while (ctx.measureText(`${last}...`).width > maxWidth && last.length > 1) {
        last = last.slice(0, -1);
      }
      lines[lines.length - 1] = `${last}...`;
    }
  }

  lines.forEach((val, i) => ctx.fillText(val, x, y + i * lineHeight));
  return lines.length * lineHeight;
}

/**
 * Loads an image from a URL and returns a Promise. Never hangs: resolves
 * null after the timeout so a stalled avatar CDN can't freeze an export.
 */
function loadImage(url, timeoutMs = 6000) {
  return new Promise((resolve) => {
    if (!url) { resolve(null); return; }
    let done = false;
    const finish = (value) => { if (!done) { done = true; resolve(value); } };
    const timer = setTimeout(() => finish(null), timeoutMs);
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => { clearTimeout(timer); finish(img); };
    img.onerror = () => { clearTimeout(timer); finish(null); };
    img.src = url;
  });
}

/**
 * Main composition for the seller trading card.
 */
async function composeSellerCard(ctx, seller, width, height, t) {
  // Background Grid & Glow
  ctx.fillStyle = t.bg;
  ctx.fillRect(0, 0, width, height);
  
  const gradient = ctx.createRadialGradient(width * 0.8, height * 0.2, 0, width * 0.8, height * 0.2, 600);
  gradient.addColorStop(0, t.glowPrimary);
  gradient.addColorStop(1, "transparent");
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, width, height);

  ctx.strokeStyle = t.grid;
  ctx.lineWidth = 1;
  const gridSize = 40;
  for (let x = 0; x <= width; x += gridSize) {
    ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, height); ctx.stroke();
  }
  for (let y = 0; y <= height; y += gridSize) {
    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(width, y); ctx.stroke();
  }

  // Header
  ctx.font = `900 12px ${MONO}`;
  ctx.fillStyle = t.accent;
  ctx.beginPath(); ctx.arc(62, 46, 4, 0, Math.PI * 2); ctx.fill();
  ctx.fillText("CMI SELLER PROFILE", 74, 50);
  
  ctx.fillStyle = t.subtle;
  ctx.textAlign = "right";
  ctx.font = `700 11px ${MONO}`;
  ctx.fillText(new Date().toISOString().replace("T", " ").split(".")[0] + " UTC", width - 56, 50);
  ctx.textAlign = "left";

  // Profile Section
  const avatarUrl = `https://render.crafty.gg/3d/bust/${encodeURIComponent(seller.name)}`;
  const avatar = await loadImage(avatarUrl);
  const avatarSize = 180;
  const avatarX = 64;
  const avatarY = 120;
  
  fillRoundRect(ctx, avatarX, avatarY, avatarSize, avatarSize, 24, t.surface, t.border);
  if (avatar) {
    ctx.drawImage(avatar, avatarX + 10, avatarY + 10, avatarSize - 20, avatarSize - 20);
  } else {
    ctx.font = `900 48px ${SANS}`;
    ctx.fillStyle = t.subtle;
    ctx.textAlign = "center";
    ctx.fillText(seller.name.slice(0, 2).toUpperCase(), avatarX + avatarSize / 2, avatarY + avatarSize / 2 + 18);
    ctx.textAlign = "left";
  }

  // Seller Name & Verified Badge — shrink-to-fit, then ellipsis.
  const nameX = avatarX + avatarSize + 40;
  const nameY = avatarY + 60;
  const maxNameWidth = width - nameX - 100;
  let nameSize = 72;
  let nameWidth = 0;
  ctx.letterSpacing = "-0.02em";
  while (nameSize > 40) {
    ctx.font = `900 ${nameSize}px ${SANS}`;
    nameWidth = Math.ceil(ctx.measureText(seller.name).width);
    if (nameWidth <= maxNameWidth) break;
    nameSize -= 8;
  }
  let displayName = seller.name;
  if (nameWidth > maxNameWidth) {
    while (nameWidth > maxNameWidth && displayName.length > 1) {
      displayName = displayName.slice(0, -1);
      nameWidth = Math.ceil(ctx.measureText(`${displayName}…`).width);
    }
    displayName = `${displayName}…`;
  }
  ctx.font = `900 ${nameSize}px ${SANS}`;
  ctx.fillStyle = t.text;
  ctx.fillText(displayName, nameX, nameY);
  ctx.letterSpacing = "normal";

  // High-inventory, market-aligned sellers earn the verified badge on the
  // card even without a manual grant — visibility matches reach.
  const band = sellerPricingBand(seller.accuracyLabel, seller.legacyAutoFlagged);
  const autoVerified = band === "Market-aligned" && Number(seller.totalListings || 0) >= 10;

  if (seller.isVerified || autoVerified) {
    const badgeX = nameX + Math.min(nameWidth, maxNameWidth) + 15;
    drawVerifiedBadge(ctx, badgeX, nameY - 55, 48, t);
  }

  // Identity / Platform
  ctx.font = `700 16px ${MONO}`;
  ctx.fillStyle = t.subtle;
  const isBedrock = seller.identityKey?.startsWith("bedrock");
  const platform = isBedrock ? "BEDROCK EDITION" : seller.uuid ? `JAVA · ${seller.uuid.slice(0, 8).toUpperCase()}` : "PLATFORM UNKNOWN";
  ctx.fillText(platform, nameX, nameY + 40);

  // Automatically derived pricing-alignment chip. This is not a trust score.
  const pricingBand = sellerPricingBand(seller.accuracyLabel, seller.legacyAutoFlagged).toUpperCase();
  const label = pricingBand;
  const labelColor = label === "MARKET-ALIGNED" ? t.emerald : label === "MIXED PRICING" ? t.muted : label === "FREQUENTLY ABOVE RANGE" ? t.accent : t.red;
  
  ctx.font = `800 14px ${MONO}`;
  const labelW = ctx.measureText(label).width + 24;
  fillRoundRect(ctx, nameX, nameY + 65, labelW, 32, 6, labelColor + "1A", labelColor + "33");
  ctx.fillStyle = labelColor;
  ctx.fillText(label, nameX + 12, nameY + 86);

  // Stats Grid
  const statsY = 400;
  const statsH = 200;
  const cardW = (width - 128 - 48) / 3;
  
  const drawStatCard = (x, title, value, sub, color) => {
    fillRoundRect(ctx, x, statsY, cardW, statsH, 20, t.surface, t.border);
    ctx.font = `800 12px ${MONO}`;
    ctx.fillStyle = t.muted;
    ctx.fillText(title.toUpperCase(), x + 24, statsY + 40);
    
    ctx.font = `900 48px ${SANS}`;
    ctx.fillStyle = color || t.text;
    ctx.fillText(value, x + 24, statsY + 110);
    
    ctx.font = `700 14px ${MONO}`;
    ctx.fillStyle = t.subtle;
    ctx.fillText(sub.toUpperCase(), x + 24, statsY + 150);
  };

  const markup = seller.avgMarkupPercent || 0;
  const markupColor = markup > 15 ? t.red : markup < -5 ? t.emerald : t.text;

  drawStatCard(64, "Inventory", String(seller.totalListings || 0), "Total active listings", t.text);
  drawStatCard(64 + cardW + 24, "Market Bias", `${markup > 0 ? "+" : ""}${markup.toFixed(1)}%`, "Avg markup vs median", markupColor);
  drawStatCard(64 + (cardW + 24) * 2, "Above Range", `${(seller.overpricedRatio || 0).toFixed(1)}%`, "Observed offers", t.text);

  // Standout offers — best-value listings with vs-median markup, mirroring
  // the seller panel rows. Fills the lower zone; falls back to the
  // disclaimer-only layout when there is nothing comparable to show.
  const stripListings = Array.isArray(seller.listings) ? seller.listings.slice(0, 5) : [];
  const stripTotal = Number(seller.listingsTotal || 0);
  const overflowCount = stripTotal > stripListings.length ? stripTotal - stripListings.length : 0;

  const TONE_COLORS = { high: t.red, above: t.warning, below: t.emerald, aligned: t.sky, neutral: t.muted };
  const stripIcons = await Promise.all(stripListings.map((listing) => loadImage(listing.iconSrc)));

  let bioY;
  if (stripListings.length > 0) {
    const stripLabelY = statsY + statsH + 40;
    ctx.font = `800 12px ${MONO}`;
    ctx.fillStyle = t.muted;
    ctx.fillText("LATEST LISTINGS · VS MEDIAN", 64, stripLabelY);

    const rowH = 54;
    const rowY0 = stripLabelY + 22;
    const priceRight = width - 64;
    const ICON_SLOT = 30;
    stripListings.forEach((listing, index) => {
      const rowY = rowY0 + index * rowH;
      if (index > 0) {
        ctx.strokeStyle = t.border;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(64, rowY);
        ctx.lineTo(priceRight, rowY);
        ctx.stroke();
      }

      // Item icon slot (always reserved so rows stay aligned)
      fillRoundRect(ctx, 64, rowY + 12, ICON_SLOT, ICON_SLOT, 8, t.surface, t.border);
      const icon = stripIcons[index];
      if (icon) {
        const wasSmooth = ctx.imageSmoothingEnabled;
        if (listing.iconPixelated !== false) ctx.imageSmoothingEnabled = false;
        try { ctx.drawImage(icon, 64 + 4, rowY + 12 + 4, ICON_SLOT - 8, ICON_SLOT - 8); } catch { /* ignore */ }
        ctx.imageSmoothingEnabled = wasSmooth;
      } else {
        ctx.font = `900 14px ${SANS}`;
        ctx.fillStyle = t.subtle;
        ctx.textAlign = "center";
        ctx.fillText("?", 64 + ICON_SLOT / 2, rowY + 12 + 21);
        ctx.textAlign = "left";
      }

      const nameX = 64 + ICON_SLOT + 8;
      ctx.font = `800 17px ${MONO}`;
      const priceWidth = Math.ceil(ctx.measureText(listing.priceLabel || "—").width);
      const nameMax = Math.max(40, priceRight - priceWidth - 20 - nameX);
      ctx.font = `700 18px ${SANS}`;
      ctx.fillStyle = t.text;
      drawTextLines(ctx, listing.name || "Unknown item", nameX, rowY + 26, nameMax, 19, 1);

      const offers = Number(listing.offers || 0);
      ctx.font = `600 10px ${MONO}`;
      ctx.fillStyle = t.muted;
      ctx.fillText(
        `MED ${listing.medianLabel || "—"} · ${offers} OFFER${offers === 1 ? "" : "S"}`,
        nameX, rowY + 44
      );

      ctx.font = `800 17px ${MONO}`;
      ctx.fillStyle = t.text;
      ctx.textAlign = "right";
      ctx.fillText(listing.priceLabel || "—", priceRight, rowY + 24);
      ctx.textAlign = "left";

      ctx.font = `800 10px ${MONO}`;
      ctx.fillStyle = TONE_COLORS[listing.tone] || t.muted;
      ctx.textAlign = "right";
      ctx.fillText(String(listing.markupText || "").toUpperCase(), priceRight, rowY + 42);
      ctx.textAlign = "left";
    });

    let cursorY = rowY0 + stripListings.length * rowH;
    if (overflowCount > 0) {
      ctx.font = `700 11px ${MONO}`;
      ctx.fillStyle = t.subtle;
      ctx.fillText(`+${overflowCount} MORE LISTING${overflowCount === 1 ? "" : "S"}`, 64, cursorY + 26);
      cursorY += 34;
    }
    bioY = cursorY + 34;
  } else {
    // Bottom Content / Info
    bioY = statsY + statsH + 50; // Reduced spacing from stats cards
  }
  ctx.font = `600 22px ${SANS}`; // Removed italic, adjusted size
  ctx.fillStyle = t.muted;
  const bio = "Pricing alignment is calculated from observed listings versus item medians. It is not a reputation, conduct, or trust rating.";
  drawTextLines(ctx, bio, 64, bioY, width - 128, 30, 2);

  // Footer
  ctx.save();
  ctx.font = `800 10px ${MONO}`;
  ctx.fillStyle = t.subtle;
  ctx.fillText("CASTIA MARKET INSIGHT · SELLER SNAPSHOT", 64, height - 32);
  ctx.textAlign = "right";
  ctx.fillText("LATEST OBSERVED LISTING DATA", width - 64, height - 32);
  ctx.restore();
}

/**
 * Public API to render the seller card and return it as a Blob.
 */
export async function renderSellerCardToBlob(seller) {
  const width = 1080;
  const height = 1080; // Square compact format
  
  return new Promise((resolve, reject) => {
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");
    if (!ctx) { reject(new Error("Canvas context failed")); return; }

    const t = themeColors();

    // Wait for webfonts so the PNG never bakes in fallback type, then
    // render in a single pass.
    const boot = (async () => {
      try { await document.fonts.ready; } catch { /* ignore */ }
    })();
    boot.then(
      () => composeSellerCard(ctx, seller, width, height, t),
      () => composeSellerCard(ctx, seller, width, height, t)
    ).then(() => {
      // Performance optimization: Render in a single pass
      canvas.toBlob((blob) => {
        if (blob) resolve(blob);
        else reject(new Error("Blob conversion failed"));
      }, "image/png");
    }).catch(reject);
  });
}
import { sellerPricingBand } from "./sellerPricing";
